//! ROM words of the pitch group, dumped from the 2.10 ELF images (`.const`).
//! Floats are kept as their IEEE words; [`f`] converts them.

/// An IEEE single from its ROM word.
pub const fn f(word: u32) -> f32 {
    f32::from_bits(word)
}

/// A Q31 ROM word as a float.
pub const fn q31(word: u32) -> f32 {
    word as i32 as f32 / 2_147_483_648.0
}

